   312  bool XCFImageFormat::readXCF(QIODevice *device, QImage *outImage)
   313  {
   314      XCFImage xcf_image;
   315      QDataStream xcf_io(device);
   316
   317      char tag[14];;
   318
   319      if (xcf_io.readRawData(tag, sizeof(tag)) != sizeof(tag)) {
   320  //             qDebug() << "XCF: read failure on header tag";
   321          return false;
   322      }
   323      if (qstrncmp(tag, "gimp xcf", 8) != 0) {
   324  //             qDebug() << "XCF: read called on non-XCF file";
   325          return false;
   326      }
   327
   328      xcf_io >> xcf_image.width >> xcf_image.height >> xcf_image.type;
   329
   330  //  qDebug() << tag << " " << xcf_image.width << " " << xcf_image.height << " " <<  xcf_image.type;
   331      if (!loadImageProperties(xcf_io, xcf_image)) {
   332          return false;
   333      }
   334
   335      // The layers appear to be stored in top-to-bottom order. This is
   336      // the reverse of how a merged image must be computed. So, the layer
   337      // offsets are pushed onto a LIFO stack (thus, we don't have to load
   338      // all the data of all layers before beginning to construct the
   339      // merged image).
   340
   341      QStack<qint32> layer_offsets;
   342
   343      while (true) {
   344          qint32 layer_offset;
   345
   346          xcf_io >> layer_offset;
   347
   348          if (layer_offset == 0) {
   349              break;
   350          }
   351
   352          layer_offsets.push(layer_offset);
   353      }
   354
   355      xcf_image.num_layers = layer_offsets.size();
   356
   357      if (layer_offsets.size() == 0) {
   358  //      qDebug() << "XCF: no layers!"; return false;
   359      }
   360
   361      // Load each layer and add it to the image
   362      while (!layer_offsets.isEmpty()) {
   363          qint32 layer_offset = layer_offsets.pop();
   364
   365          xcf_io.device()->seek(layer_offset);
   366
   367          if (!loadLayer(xcf_io, xcf_image)) {
   368              return false;
   369          }
   370      }
   371
   372      if (!xcf_image.initialized) {
   373  //      qDebug() << "XCF: no visible layers!";
   374          return false;
   375      }
   376
   377      *outImage = xcf_image.image;
   378      return true;
   379  }
